  foreach(var row in NoteColors.Rows){panel.Children.Add(new TextBlock{Text=row.Name,FontSize=11,Foreground=Visuals.Brush(dark?"#D5D5DD":"#555561"),Margin=new Thickness(2,5,0,3)});var colors=new StackPanel{Orientation=Orientation.Horizontal};foreach(var hex in row.Colors){var c=(Color)ColorConverter.ConvertFromString(hex);var swatch=new Button{Background=Visuals.Brush(hex),Width=32,Height=32,Margin=new Thickness(2),ToolTip=row.Name+" · "+hex,Content=Note.Color==hex&&(Note.ColorMode==row.Mode||(Note.ColorMode=="Soft"&&row.Mode=="Pastel"))?"✓":"",Foreground=new SolidColorBrush(NoteColors.Text(c)),BorderBrush=Visuals.Brush("#60808080"),BorderThickness=new Thickness(1)};swatch.Click+=(_,_)=>{Note.Color=hex;Note.ColorMode=row.Mode;ApplyColor();MarkDirty();popup.IsOpen=false;};System.Windows.Automation.AutomationProperties.SetName(swatch,"Cor "+row.Name+" "+hex);colors.Children.Add(swatch);}panel.Children.Add(colors);}
